let globalCounters = {};

function incrementCounter(name, amount = 1) {
    if (!globalCounters[name]) {
        globalCounters[name] = 0;
    }
    // Read current value
    let current = globalCounters[name];
    // Simulate async work
    return new Promise(resolve => {
        setTimeout(() => {
            globalCounters[name] = current + amount;
            resolve(globalCounters[name]);
        }, Math.random() * 50);
    });
}

function getCounter(name) {
    return globalCounters[name] || 0;
}
